use crate::util::PercentDecodedStr;
use http::Extensions;
use matchit::Params;
use std::sync::Arc;

pub(crate) fn is_nested_tail_path(path: &str) -> bool {
    path.ends_with(super::NEST_TAIL_PARAM_CAPTURE)
}

pub(crate) fn strip_nested_tail_suffix(path: &str) -> &str {
    path.strip_suffix(super::NEST_TAIL_PARAM_CAPTURE)
        .unwrap_or(path)
}

pub(crate) fn is_private_capture_key(key: &str) -> bool {
    if key.starts_with(super::NEST_TAIL_PARAM) {
        true
    } else if key.starts_with(super::FALLBACK_PARAM) {
        true
    } else {
        false
    }
}

pub(crate) enum UrlParams {
    Params(Vec<(Arc<str>, PercentDecodedStr)>),
    InvalidUtf8InPathParam { key: Arc<str> },
}

pub(crate) fn insert_url_params(extensions: &mut Extensions, params: Params) {
    let current_params = extensions.get_mut();

    if let Some(UrlParams::InvalidUtf8InPathParam { .. }) = current_params {
        // nothing to do here since an error was stored earlier
        return;
    }

    let params = params
        .iter()
        .filter(|(key, _)| !is_private_capture_key(key))
        .map(|(k, v)| {
            if let Some(decoded) = PercentDecodedStr::decode_route_capture(v) {
                Ok((Arc::from(k), decoded))
            } else {
                Err(Arc::from(k))
            }
        })
        .collect::<Result<Vec<_>, _>>();

    match (current_params, params) {
        (Some(UrlParams::InvalidUtf8InPathParam { .. }), _) => {
            unreachable!("we check for this state earlier in this method")
        }
        (_, Err(invalid_key)) => {
            extensions.insert(UrlParams::InvalidUtf8InPathParam { key: invalid_key });
        }
        (Some(UrlParams::Params(current)), Ok(params)) => {
            current.extend(params);
        }
        (None, Ok(params)) => {
            extensions.insert(UrlParams::Params(params));
        }
    }
}

