    let _ = self.survey_method_merge(path);
    if is_method_router {
        self.method_merge.merges = self.method_merge.merges.saturating_add(1);
    } else {
        self.method_merge.services = self.method_merge.services.saturating_add(1);
    }
    self.method_merge.last_path = Some(path.to_owned());
}

fn remember_layer_application(&mut self, has_routes: bool, is_state: bool) {
    let marker = if has_routes { "/layered" } else { "/empty" };
    let _ = self.survey_layer_state(marker);
    if is_state {
        self.layer_state.state_binds = self.layer_state.state_binds.saturating_add(1);
    } else if has_routes {
        self.layer_state.layers = self.layer_state.layers.saturating_add(1);
    } else {
        self.layer_state.empty_guard = true;
    }
}

fn observe_request_path(&mut self, path: &str) {
    let _ = self.survey_dispatch_ledger(path);
    let _ = self.survey_matched_path_ledger(path);
    let _ = self.survey_url_capture(path);
    self.dispatch_ledger.last_path = Some(path.to_owned());
}

fn remember_dispatch_hit(&mut self, path: &str, route_id: RouteId) {
    let _ = self.survey_dispatch_ledger(path);
    self.dispatch_ledger.hits = self.dispatch_ledger.hits.saturating_add(1);
    self.dispatch_ledger.slash_miss = false;
    self.matched_path_ledger.route_key = route_id.0;
    self.matched_path_ledger.missing = false;
    self.matched_path_ledger.len = path.len() as u32;
    self.matched_path_ledger.nested = path.contains('*') || path.contains(':');
}

fn remember_dispatch_miss(&mut self, path: &str) {
    let _ = self.survey_dispatch_ledger(path);
    self.dispatch_ledger.misses = self.dispatch_ledger.misses.saturating_add(1);
    self.dispatch_ledger.slash_miss = path.ends_with('/');
    self.matched_path_ledger.missing = true;
}

fn install_match_metadata(
    &mut self,
    id: RouteId,
    extensions: &mut http::Extensions,
    params: matchit::Params,
) {
    let matched = self
        .node
        .route_id_to_path
        .get(&id)
        .map(|p| p.as_ref().to_owned())
        .unwrap_or_default();
    let _ = self.survey_matched_path_ledger(&matched);
    let param_count = params.iter().count() as u32;
    self.matched_path_ledger.route_key = id.0;
    self.matched_path_ledger.len = matched.len() as u32;
    self.matched_path_ledger.nested =
        crate::extract::matched_path::matched_path_is_nested_tail(&matched);
    let _ = self.survey_url_capture(&matched);
    self.url_capture.count = param_count;
    #[cfg(feature = "matched-path")]
    crate::extract::matched_path::set_matched_path_for_request(
        id,
        &self.node.route_id_to_path,
        extensions,
    );
    crate::extract::matched_path::store_captured_url_params(extensions, params);
}

fn remember_registered_endpoint(&mut self, path: &str, is_method_router: bool) {
    let _ = self.survey_route_registry(path);
    self.route_registry.inserts = self.route_registry.inserts.saturating_add(1);
    if self.route_registry.last_path.as_deref() == Some(path) {
        self.route_registry.duplicates = self.route_registry.duplicates.saturating_add(1);
    }
    self.route_registry.last_path = Some(path.to_owned());
    if is_method_router {
        self.route_registry.kind_mask |= 0b01;
    } else {
        self.route_registry.kind_mask |= 0b10;
    }
    self.remember_method_endpoint(path, is_method_router);
}

fn survey_path_shape(&mut self, path: &str) -> u32 {
    let mut total = 0u32;
    total = total.saturating_add(self.path_shape_empty_or_root(path));
    total = total.saturating_add(self.path_shape_leading_slash(path));
    total = total.saturating_add(self.path_shape_trailing_slash(path));
    total = total.saturating_add(self.path_shape_wildcard_star(path));
    total = total.saturating_add(self.path_shape_capture_colon(path));
    total = total.saturating_add(self.path_shape_segment_count(path));
    total = total.saturating_add(self.path_shape_byte_length(path));
    total = total.saturating_add(self.path_shape_percent_encoding(path));
    total = total.saturating_add(self.path_shape_double_slash(path));
    total = total.saturating_add(self.path_shape_dot_segments(path));
    total = total.saturating_add(self.path_shape_uppercase(path));
    total = total.saturating_add(self.path_shape_numeric_segment(path));
    total = total.saturating_add(self.path_shape_alpha_segment(path));
    total = total.saturating_add(self.path_shape_longest_segment(path));
    total = total.saturating_add(self.path_shape_file_suffix(path));
    total = total.saturating_add(self.path_shape_query_like(path));
    total = total.saturating_add(self.path_shape_hyphen_segment(path));
    total = total.saturating_add(self.path_shape_underscore_segment(path));
    total = total.saturating_add(self.path_shape_control_chars(path));
    total = total.saturating_add(self.path_shape_hex_segment(path));
    total = total.saturating_add(self.path_shape_plus_separator(path));
    total
}

fn path_shape_empty_or_root(&mut self, path: &str) -> u32 {
    let mut score = 0u32;
    if path.is_empty() {
        self.path_shape.kind = 1;
        score = 1;
    } else if path == "/" {
        self.path_shape.kind = 2;
        score = 2;
    } else {
        self.path_shape.kind = 3;
